mapper.select:
SELECT ID, ORG_NAME AS organization, ALIAS, ORG_OWNER, TENANT_ID AS tenant_id, PARENT_ID, ORG_RANK AS org_rank, CREATE_DATE , REMARKS, PARENT_KEYS AS parentKeys, ORG_CATEGORY, ENABLED, ORG_TYPE, ORDER_NO FROM LA_ORGANIZATION O
AND O.ORG_OWNER = #{parameters.owner}
AND O.ORG_OWNER IS NULL
AND O.ORG_NAME LIKE #{parameters.name}
AND O.ALIAS LIKE #{parameters.alias}
AND O.ID IN
#{item}
ORDER BY O.ORG_RANK, O.ORDER_NO, O.PARENT_ID, O.ORG_NAME

SELECT ID, ALIAS AS name, PARENT_ID AS pid FROM LA_ORGANIZATION O WHERE O.ENABLED = 1
AND O.ORG_OWNER = #{parameters.owner}
AND O.ORG_OWNER IS NULL
AND O.PARENT_KEYS LIKE #{parameters.parentKeys}
ORDER BY O.ORG_RANK, O.ORDER_NO, O.PARENT_ID, O.ORG_NAME

mapper.update:
UPDATE LA_USERS T SET T.enabled = #{enabled} WHERE T.username IN (
    SELECT T2.USERNAME FROM LA_USER_ORGANIZATION T2
    INNER JOIN LA_ORGANIZATION T3 ON T2.ORGANIZATION_ID = T3.ID
    WHERE T3.ID IN
    #{item}
)

UPDATE LA_ORGANIZATION T SET
T.ORG_RANK = CASE

    WHEN ID = #{item.id} THEN #{item.level}

END,
PARENT_ID = CASE

    WHEN ID = #{item.id} THEN #{item.parentId}

END,
PARENT_KEYS = CASE

    WHEN ID = #{item.id} THEN #{item.parentKeys}

END,
ORDER_NO = CASE

    WHEN ID = #{item.id} THEN #{item.orderNo}

END
WHERE ID IN

    #{item.id}
